(() => {
  window.__bcSrcs = [...document.querySelectorAll('.banner-card img')].map((i) => i.src);
  const cards = [...document.querySelectorAll('.banner-card')];
  if (cards.length !== 4) throw new Error('cards=' + cards.length);
  if (document.querySelector('.banner-card-reroll')) throw new Error('a per-banner randomizer is still sitting on the artwork');
  if (document.querySelector('.banner-card-tag')) throw new Error('number tags still rendered');
  const head = document.querySelector('.banners-head');
  if (!head) throw new Error('no banners head');
  const btns = [...head.querySelectorAll('button.refresh')];
  if (btns.length !== 1) throw new Error('randomizers beside the banners title: ' + btns.length + ', need exactly 1');
  if (document.querySelectorAll('.banners button.refresh').length !== 1) throw new Error('a stray randomizer is loose in the banner section');
  const title = head.querySelector('.stage-title');
  if (!title) throw new Error('banners title is not the same element the profile picture section uses');
  const titleRect = title.getBoundingClientRect();
  const btnRect = btns[0].getBoundingClientRect();
  if (btnRect.left < titleRect.right - 1) throw new Error('randomizer is not beside the title');
  if (Math.abs((btnRect.top + btnRect.bottom) / 2 - (titleRect.top + titleRect.bottom) / 2) > 3) throw new Error('randomizer is not level with the title');
  const pfp = document.querySelector('.stage .stage-head button.refresh');
  if (!pfp) throw new Error('profile picture section lost its randomizer');
  const pfpRect = pfp.getBoundingClientRect();
  if (Math.abs(pfpRect.width - btnRect.width) > 1) throw new Error('banner randomizer is ' + Math.round(btnRect.width) + 'px, profile picture one is ' + Math.round(pfpRect.width) + 'px');
  if (cards.some((c) => !c.querySelector('img'))) throw new Error('a card has no render');
  const g = document.querySelector('.banners-grid').getBoundingClientRect();
  const stage = document.querySelector('.stage');
  const cs = getComputedStyle(stage);
  const inner = stage.getBoundingClientRect().width - parseFloat(cs.paddingLeft) - parseFloat(cs.paddingRight);
  const grid = document.querySelector('.grid').getBoundingClientRect();
  if (g.top < grid.bottom) throw new Error('banners overlap the profile grid');
  if (Math.abs(g.left - titleRect.left) > 2) throw new Error('banners grid off the title edge');
  if (Math.abs(g.width - inner) > 2) throw new Error('grid width ' + Math.round(g.width) + ' vs stage ' + Math.round(inner));
  const ratios = cards.map((c) => { const r = c.getBoundingClientRect(); return r.width / r.height; });
  const bad = ratios.find((r) => Math.abs(r - 1546 / 423) > 0.02);
  if (bad) throw new Error('card aspect ' + bad.toFixed(3));
  if (new Set(cards.map((c) => Math.round(c.getBoundingClientRect().top))).size !== 1) throw new Error('cards are not on one row');
  return ('4 cards, 1 randomizer beside the title (' + Math.round(btnRect.width) + 'px, same as the profile picture one), grid ' + Math.round(g.width) + 'px at card aspect ' + ratios[0].toFixed(3));
})()

(() => {
  const before = window.__bcSrcs;
  const now = [...document.querySelectorAll('.banner-card img')].map((i) => i.src);
  if (now.length !== before.length) throw new Error('card count changed');
  const changed = now.filter((src, i) => src !== before[i]).length;
  if (changed !== now.length) throw new Error(changed + ' of ' + now.length + ' banners re-rolled — one press must move all of them');
  throw new Error('one press re-rolled all ' + changed + ' banners together');
})()

(() => {
  const L = window.__bcBannerLayout;
  if (!L) throw new Error('no layout probe');
  if (L.order.join('>') !== 'bg>left>right>text') throw new Error('paint order ' + L.order.join('>'));
  if (Math.abs(L.width / L.height - 16 / 9) > 0.01) throw new Error('frame aspect ' + (L.width / L.height).toFixed(3));
  if (Math.abs(L.strip.x + L.strip.w / 2 - L.width / 2) > 1) throw new Error('strip off centre');
  if (Math.abs(L.text.x + L.text.w / 2 - L.width / 2) > 1) throw new Error('wordmark box off centre');
  const flushL = Math.abs(L.left.x - L.strip.x);
  const flushR = Math.abs(L.right.x + L.right.w - (L.strip.x + L.strip.w));
  if (flushL > 1 || flushR > 1) throw new Error('figure is not pinned to the strip edge: left ' + flushL.toFixed(1) + ' right ' + flushR.toFixed(1));
  if (L.left.y + L.left.h > L.strip.y + L.strip.h + 1) throw new Error('figure hangs below the strip floor');

  const img = document.querySelector('.download-preview.is-banner img');
  const c = document.createElement('canvas');
  c.width = img.naturalWidth;
  c.height = img.naturalHeight;
  const x = c.getContext('2d');
  x.drawImage(img, 0, 0);
  const W = c.width;
  const H = c.height;
  const d = x.getImageData(0, 0, W, H).data;
  const rgb = (X, Y) => { const i = (Y * W + X) * 4; return d[i] + ',' + d[i + 1] + ',' + d[i + 2]; };

  const corners = [rgb(4, 4), rgb(W - 5, 4), rgb(4, H - 5), rgb(W - 5, H - 5), rgb(Math.round(W / 2), 6), rgb(Math.round(W / 2), H - 6)];
  if (!corners.every((v) => v === corners[0])) throw new Error('outside the strip is not flat: ' + corners.join(' | '));
  const bg = corners[0];

  const yTop = Math.round(L.strip.y);
  const yBot = Math.round(L.strip.y + L.strip.h) - 1;
  const edge = (X) => {
    let ink = 0;
    let run = 0;
    let best = 0;
    for (let Y = yTop; Y <= yBot; Y += 1) {
      if (rgb(X, Y) === bg) { run = 0; continue; }
      ink += 1;
      run += 1;
      if (run > best) best = run;
    }
    return { ink, best };
  };
  const eL = edge(Math.round(L.strip.x) + 1);
  const eR = edge(Math.round(L.strip.x + L.strip.w) - 2);
  if (eL.ink < 2 || eR.ink < 2) throw new Error('figure does not reach the strip edge: left ink ' + eL.ink + ' right ink ' + eR.ink);
  const limit = L.strip.h * 0.85;
  if (eL.best > limit || eR.best > limit) throw new Error('figure is sliced flat down the strip edge: run left ' + eL.best + ' right ' + eR.best);

  const gx0 = Math.round(L.left.x + L.left.w);
  const gx1 = Math.round(L.right.x) - 1;
  let ink = 0;
  let sumX = 0;
  let minX = W;
  let maxX = -1;
  for (let Y = Math.round(L.text.y); Y <= Math.round(L.text.y + L.text.h); Y += 1) {
    for (let X = gx0; X <= gx1; X += 1) {
      const i = (Y * W + X) * 4;
      if (d[i + 3] < 200) continue;
      if (rgb(X, Y) === bg) continue;
      ink += 1;
      sumX += X;
      if (X < minX) minX = X;
      if (X > maxX) maxX = X;
    }
  }
  if (ink < 200) throw new Error('no wordmark ink between the busts: ' + ink);
  const drift = Math.abs(sumX / ink - W / 2);
  if (drift > 4) throw new Error('wordmark ink off centre by ' + drift.toFixed(1) + 'px');
  const inkW = maxX - minX + 1;
  if (inkW > gx1 - gx0 + 1) throw new Error('wordmark ink wider than the clearance');

  throw new Error('frame=' + W + 'x' + H + ' flush=' + Math.max(flushL, flushR).toFixed(1) + 'px edgeInk=' + eL.ink + '/' + eR.ink + ' maxRun=' + Math.max(eL.best, eR.best) + '/' + Math.round(L.strip.h) + ' ink=' + ink + ' drift=' + drift.toFixed(1) + 'px inkW=' + inkW + '/' + (gx1 - gx0 + 1) + ' gap=' + Math.round(L.text.w) + ' bustAspect=' + (L.left.w / L.left.h).toFixed(2));
})()

(() => {
  const L = window.__bcBannerLayout;
  if (L.width !== 2560 || L.height !== 1440) throw new Error('export ' + L.width + 'x' + L.height);
  if (L.bytes < 30000) throw new Error('export too small: ' + L.bytes);
  if (L.bytes > 6000000) throw new Error('over the YouTube cap: ' + L.bytes);
  const flushL = Math.abs(L.left.x - L.strip.x);
  const flushR = Math.abs(L.right.x + L.right.w - (L.strip.x + L.strip.w));
  if (flushL > 2 || flushR > 2) throw new Error('export figure is not pinned to the strip edge: ' + flushL.toFixed(1) + '/' + flushR.toFixed(1));
  if (Math.abs(L.text.x + L.text.w / 2 - L.width / 2) > 2) throw new Error('wordmark box off centre in the export');
  if (Math.abs(L.strip.w / L.width - 1546 / 2560) > 0.001) throw new Error('strip is not the same fraction of the frame');
  if (L.left.y + L.left.h > L.strip.y + L.strip.h + 2) throw new Error('export figure hangs below the strip floor');
  throw new Error('export=' + L.width + 'x' + L.height + ' bytes=' + L.bytes + ' ms=' + L.ms + ' flush=' + Math.max(flushL, flushR).toFixed(1) + 'px bustAspect=' + (L.left.w / L.left.h).toFixed(3) + ' textBox=' + Math.round(L.text.w) + 'px (' + (100 * L.text.w / L.width).toFixed(2) + '% of frame)');
})()
